-- GENERATED by scripts/generate-setup-sql.mjs - do not edit by hand.
-- Every numbered migration, concatenated in order. Idempotent: safe to
-- run on a fresh database AND on one that already has some migrations
-- applied (each statement is IF NOT EXISTS / additive).

-- ============ 0001_init.sql ============
-- SEO Manager MVP - initial schema.
-- Single user. Access is server-side only via the service role key.
-- RLS is ENABLED with zero policies on every table: that makes the anon and
-- authenticated PostgREST roles see nothing, while the service role bypasses
-- RLS entirely. This is the "no RLS complexity" posture without leaving the
-- tables open to anyone holding the public anon key.

-- pages first: keywords.target_page_id references it.
create table if not exists pages (
  id uuid primary key default gen_random_uuid(),
  url text not null unique,
  title text,
  type text,                          -- guide | tool | landing
  primary_keyword text,
  published_at timestamptz,
  pr_url text,
  created_at timestamptz default now()
);

-- tracked keywords
create table if not exists keywords (
  id uuid primary key default gen_random_uuid(),
  keyword text not null unique,
  search_volume int,
  keyword_difficulty numeric,
  cpc numeric,
  intent text,                        -- informational/commercial/etc
  status text default 'tracking',     -- tracking | paused
  target_page_id uuid references pages(id),
  created_at timestamptz default now()
);

-- rank history (one row per keyword per check)
create table if not exists rank_checks (
  id uuid primary key default gen_random_uuid(),
  keyword_id uuid references keywords(id) on delete cascade,
  position int,                       -- null = not in top 100
  url text,                           -- which page ranks
  checked_at timestamptz default now()
);

-- the daily cron reads/writes per keyword ordered by time
create index if not exists rank_checks_keyword_checked_idx
  on rank_checks (keyword_id, checked_at desc);

-- the suggestions queue (heart of the system)
create table if not exists suggestions (
  id uuid primary key default gen_random_uuid(),
  type text not null,                 -- guide | tool | backlink | update
  title text not null,
  primary_keyword text,
  keyword_volume int,
  keyword_difficulty numeric,
  rationale text,                     -- why this is worth doing
  spec jsonb,                         -- brief: outline, angle, tool functionality, target url for backlinks
  status text default 'pending',      -- pending | approved | rejected | in_progress | done
  result_pr_url text,
  created_at timestamptz default now(),
  decided_at timestamptz,
  completed_at timestamptz
);

-- daily GSC snapshot
create table if not exists gsc_stats (
  id uuid primary key default gen_random_uuid(),
  date date not null unique,
  clicks int,
  impressions int,
  ctr numeric,
  avg_position numeric,
  top_queries jsonb,                  -- [{query, clicks, impressions, position}] top 20
  top_pages jsonb
);

-- backlink prospects
create table if not exists backlink_prospects (
  id uuid primary key default gen_random_uuid(),
  domain text not null,
  url text,
  domain_rating numeric,
  reason text,                        -- why relevant / where found
  status text default 'new',          -- new | contacted | acquired | rejected
  created_at timestamptz default now()
);

alter table pages enable row level security;
alter table keywords enable row level security;
alter table rank_checks enable row level security;
alter table suggestions enable row level security;
alter table gsc_stats enable row level security;
alter table backlink_prospects enable row level security;

-- ============ 0002_playbook_status.sql ============
-- Playbook progress: which foundational-backlink items the user has completed.
-- One row per playbook item slug (the curated registry lives in code at
-- src/lib/playbook-data.ts - only the per-user progress is stored here).
-- Same RLS posture as 0001: enabled with no policies, so only the service-role
-- client (src/lib/db.ts) can read/write.

create table if not exists playbook_status (
  slug text primary key,
  status text not null default 'todo' check (status in ('todo', 'done', 'skipped')),
  done_at timestamptz
);

alter table playbook_status enable row level security;

-- ============ 0003_site_profile.sql ============
-- Site profile: the product identity the backlink playbook personalizes from
-- (name, tagline, descriptions at directory-friendly lengths, categories,
-- tags). Written by the /seo-setup agent command via the set_site_profile MCP
-- tool; read by the dashboard to prefill every playbook submission and
-- @browser command.
--
-- Single-tenant: one row, id locked to 1. The future multi-tenant version
-- replaces this with per-tenant rows keyed to an account.
-- Same RLS posture as 0001/0002: enabled, no policies, service-role only.

create table if not exists site_profile (
  id int primary key default 1 check (id = 1),
  name text not null,
  url text not null,
  tagline text not null,          -- <= 60 chars, fits most directory tagline limits
  short_description text not null, -- <= 160 chars, meta-description-sized fields
  long_description text not null,  -- 300-600 chars, roomy description fields
  categories text[] not null default '{}',
  tags text[] not null default '{}',
  updated_at timestamptz not null default now()
);

alter table site_profile enable row level security;

-- No seed. The dashboard shows its "set up your site profile" card (and the
-- agent's /seo-setup writes the row) once the owner's real site exists - a
-- fresh instance must never be born describing someone else's product.
-- (Until 2026-07-21 this seeded ClockedCode, this repo's original tenant;
-- existing installs keep whatever row they already have.)

-- ============ 0004_projects.sql ============
-- 0004: projects - the tenant axis. One deployment now manages many sites:
-- every operational table gains a project_id, and the dashboard grows a
-- Vercel-style project switcher.
--
-- Zero-downtime plan: project_id gets a DEFAULT of the ClockedCode project's
-- FIXED id, so code deployed before this migration keeps writing valid rows
-- during the migration->deploy window, and old rows backfill automatically
-- (ADD COLUMN ... DEFAULT fills existing rows).

create extension if not exists pgcrypto;

create table if not exists projects (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  domain text not null unique,              -- bare domain: clockedcode.com
  gsc_site_url text,                        -- GSC property (sc-domain:... or https://...); null until connected
  github_repo text,                         -- owner/repo the content PRs land in; null = no pipeline yet
  mcp_token text not null unique,           -- per-project bearer for the MCP server and CI workflows
  location_code int not null default 2840,  -- DataForSEO market (2840 = US)
  language_code text not null default 'en',
  mode text not null default 'semi' check (mode in ('semi', 'auto')),
  created_at timestamptz not null default now()
);
-- Same posture as every other table here: RLS on, zero policies - only the
-- service-role key (the dashboard + MCP server) can read or write.
alter table projects enable row level security;

-- Project #1, with a FIXED id so it can be the column default below. Seeded
-- NEUTRAL: the onboarding wizard claims this row in place for the owner's
-- first site (keeping the fixed id every project_id default points at), so
-- a fresh instance is never born configured for someone else's product.
-- The legacy MCP_API_KEY env var maps to this row by its fixed id, whatever
-- slug/name the wizard later gives it. Conflict target is the id: existing
-- installs (whose row may be renamed, or the pre-2026-07-21 ClockedCode
-- seed) keep their row untouched.
insert into projects (id, slug, name, domain, gsc_site_url, github_repo, mcp_token, mode)
values (
  '00000000-0000-4000-8000-000000000001',
  'default',
  'Your site',
  '',
  null,
  null,
  encode(gen_random_bytes(24), 'hex'),
  'semi'
)
on conflict (id) do nothing;

-- ---- add project_id everywhere (default = ClockedCode) ---------------------

alter table pages              add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);
alter table keywords           add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);
alter table rank_checks        add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);
alter table suggestions        add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);
alter table gsc_stats          add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);
alter table backlink_prospects add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);
alter table playbook_status    add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);
alter table site_profile       add column if not exists project_id uuid not null default '00000000-0000-4000-8000-000000000001' references projects(id);

-- ---- retarget the uniqueness that assumed one site -------------------------

-- keyword text was globally unique; now unique per project.
alter table keywords drop constraint if exists keywords_keyword_key;
create unique index if not exists keywords_project_keyword_key on keywords (project_id, keyword);

-- page url was globally unique; now unique per project.
alter table pages drop constraint if exists pages_url_key;
create unique index if not exists pages_project_url_key on pages (project_id, url);

-- one GSC snapshot per day PER PROJECT.
alter table gsc_stats drop constraint if exists gsc_stats_date_key;
create unique index if not exists gsc_stats_project_date_key on gsc_stats (project_id, date);

-- playbook progress: one row per (project, item) instead of per item.
alter table playbook_status drop constraint if exists playbook_status_pkey;
alter table playbook_status add primary key (project_id, slug);

-- site_profile: one row per project instead of the single id=1 row. The id
-- column stays as pk but gets a sequence so new projects can insert rows.
alter table site_profile drop constraint if exists site_profile_id_check;
create sequence if not exists site_profile_id_seq owned by site_profile.id;
select setval('site_profile_id_seq', greatest((select coalesce(max(id), 1) from site_profile), 1));
alter table site_profile alter column id set default nextval('site_profile_id_seq');
create unique index if not exists site_profile_project_key on site_profile (project_id);

-- ---- filter indexes for the per-project queries ----------------------------

create index if not exists suggestions_project_idx        on suggestions (project_id, created_at);
create index if not exists rank_checks_project_idx        on rank_checks (project_id, checked_at desc);
create index if not exists backlink_prospects_project_idx on backlink_prospects (project_id, created_at desc);

-- ============ 0005_index_requested.sql ============
-- "Request Google indexing" follow-up state for published pages.
--
-- Google has no API for pushing regular pages into its index (IndexNow is
-- Bing/Yandex only; Google's Indexing API is restricted to job postings and
-- livestreams; the URL Inspection API is read-only). The fastest legitimate
-- path is a human clicking "Request indexing" in Search Console, so the
-- dashboard surfaces a next-action card for every freshly published page.
-- Marking the card done stamps this column and hides it.
alter table pages add column if not exists index_requested_at timestamptz;

comment on column pages.index_requested_at is
  'When the user marked the manual GSC "Request indexing" step done for this page. Null = still waiting (card shows on Home while the page is fresh).';

-- ============ 0006_cascade_deletes.sql ============
-- 0006: deletable projects. Deleting a projects row now cascades through every
-- table that carries its project_id, so "Delete project" is one statement and
-- can never leave orphans behind.

alter table pages
  drop constraint if exists pages_project_id_fkey,
  add constraint pages_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

alter table keywords
  drop constraint if exists keywords_project_id_fkey,
  add constraint keywords_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

alter table rank_checks
  drop constraint if exists rank_checks_project_id_fkey,
  add constraint rank_checks_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

alter table suggestions
  drop constraint if exists suggestions_project_id_fkey,
  add constraint suggestions_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

alter table gsc_stats
  drop constraint if exists gsc_stats_project_id_fkey,
  add constraint gsc_stats_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

alter table backlink_prospects
  drop constraint if exists backlink_prospects_project_id_fkey,
  add constraint backlink_prospects_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

alter table playbook_status
  drop constraint if exists playbook_status_project_id_fkey,
  add constraint playbook_status_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

alter table site_profile
  drop constraint if exists site_profile_project_id_fkey,
  add constraint site_profile_project_id_fkey
    foreign key (project_id) references projects(id) on delete cascade;

-- Rank history dies with its keyword (it is meaningless without it).
alter table rank_checks
  drop constraint if exists rank_checks_keyword_id_fkey,
  add constraint rank_checks_keyword_id_fkey
    foreign key (keyword_id) references keywords(id) on delete cascade;

-- A keyword survives its target page - it just loses the pointer.
alter table keywords
  drop constraint if exists keywords_target_page_id_fkey,
  add constraint keywords_target_page_id_fkey
    foreign key (target_page_id) references pages(id) on delete set null;

-- ============ 0007_dataforseo_per_project.sql ============
-- 0007: per-project DataForSEO credentials - the free-tier DIY model. Each
-- project brings its own DataForSEO account, so rank checks, keyword research,
-- and Domain Rating bill the project owner, never the platform. The default
-- (ClockedCode) project keeps using the env credentials; every other project
-- gets NO env fallback - without its own credentials the SERP and DR features
-- skip gracefully and the "Connect DataForSEO" setup card shows on Home.
--
-- Same storage posture as mcp_token: the table is reachable only through the
-- service-role key (RLS on, zero policies), never from a browser.

alter table projects add column if not exists dataforseo_login text;
alter table projects add column if not exists dataforseo_password text;

-- ============ 0008_domain_ratings.sql ============
-- 0008: domain_ratings - a persistent, per-project Domain Rating snapshot.
--
-- Why this exists: DR used to live only in unstable_cache. Any
-- revalidatePath('/', ...) (project connect/switch/delete/create, and every
-- '/'-scoped mutation) counts as "revalidate all data" in Next 16, so it wiped
-- BOTH the cached value AND the fetched_at timestamp the "updates in Xh Ym"
-- timer counts down from. The timer therefore snapped back to ~24h on every
-- dashboard mutation, and - worse - each wipe re-fired the paid DataForSEO
-- backlinks-summary call on the next render, defeating the 24h cache entirely.
--
-- Persisting the snapshot in the DB makes the 24h cache real: getDomainRating
-- reads this row, refreshes from DataForSEO only when fetched_at is older than
-- 24h, and the timer reflects the true last-fetch time. A page revalidation can
-- no longer reset it.
--
-- One row per project. Cascades on project delete, same as every other table
-- (see 0006). RLS on with zero policies - the service-role key (dashboard +
-- crons) is the only reader/writer, matching the house posture.

create table if not exists domain_ratings (
  project_id        uuid primary key references projects(id) on delete cascade,
  dr                int,          -- 0-100 (raw rank / 10, rounded); null = unknown
  rank              int,          -- raw 0-1000
  referring_domains int,
  backlinks         int,
  spam_score        int,          -- 0-100
  fetched_at        timestamptz not null default now()
);

alter table domain_ratings enable row level security;

-- ============ 0009_keyword_source.sql ============
-- 0009: per-project keyword data source - the onboarding wizard's choice.
-- Three modes the engine supports end to end:
--   'dataforseo'  paid, most accurate (the pre-wizard default, so existing
--                 projects keep behaving exactly as before)
--   'serpapi'     free mode with a bring-your-own SerpApi key (250 searches/mo
--                 free tier) - live SERP checks on a weekly cadence
--   'gsc'         pure free mode - positions come from Search Console only
-- serpapi_key is stored encrypted at rest (same crypto.ts posture as the
-- DataForSEO password). powerups_skipped remembers which optional setup cards
-- the user unchecked in the wizard so Home stops showing them.

alter table projects add column if not exists keyword_source text not null default 'dataforseo'
  check (keyword_source in ('dataforseo', 'serpapi', 'gsc'));
alter table projects add column if not exists serpapi_key text;
alter table projects add column if not exists powerups_skipped text[] not null default '{}';

-- ============ 0010_indexed_verification.sql ============
-- Verified Google index state for published pages.
--
-- index_requested_at (0005) records that the manual "Request indexing" step
-- happened; these two columns record what Google actually says. The URL
-- Inspection API is read-only but that is exactly what verification needs:
-- the hourly-gsc cron asks it about every not-yet-confirmed page and stamps
-- indexed_at on a PASS verdict, so the dashboard's "Indexed" badge no longer
-- has to wait for the first impression to land. The agent's
-- mark_indexing_requested MCP tool also stamps indexed_at when Search Console
-- showed a page was already on Google.
alter table pages add column if not exists indexed_at timestamptz;
alter table pages add column if not exists index_checked_at timestamptz;

comment on column pages.indexed_at is
  'When Google was first confirmed to have this page indexed (URL Inspection API PASS, or the agent saw "URL is on Google" in Search Console). Null = not confirmed yet.';
comment on column pages.index_checked_at is
  'Last time the cron asked the URL Inspection API about this page - rotates the per-run inspection budget through the unconfirmed backlog.';

-- ============ 0011_automation_toggles.sql ============
-- 0011: per-automation toggles + the derived 'custom' publish mode.
--
-- The topbar mode is now derived from four automation flags:
--   semi   = auto_approve off, builds on, auto_merge off (you approve + merge)
--   auto   = everything on (fully hands-off)
--   custom = any other combination (set by toggling on the Automations page)
-- 'semi'/'auto' rows keep meaning the preset regardless of the flag columns;
-- the flag columns are only consulted when mode = 'custom'. Defaults are all
-- true so existing rows (both projects run auto today) keep their behavior.
--
-- Locked automations (weekly research, rank checks, GSC snapshots, tool
-- validation, IndexNow) have no columns on purpose - they cannot be disabled.

alter table projects drop constraint if exists projects_mode_check;
alter table projects
  add constraint projects_mode_check check (mode in ('semi', 'auto', 'custom'));

alter table projects
  add column if not exists auto_approve boolean not null default true,
  add column if not exists auto_build_guides boolean not null default true,
  add column if not exists auto_build_tools boolean not null default true,
  add column if not exists auto_merge boolean not null default true;

-- ============ 0012_conventions.sql ============
-- Conventions: the dashboard's mirror of each repo's .dispatchseo/conventions.md
-- - the site facts the setup workflow discovers (stack, build command, theme
-- tokens, voice rules, exemplars). Written by the agent via the set_conventions
-- MCP tool right after it writes the repo file; read by the dashboard's
-- Instructions page to show "here is how DispatchSEO adapted to YOUR site".
-- One upserted row per project (jsonb, a few KB) - current value only, the
-- repo file's git history is the archive.
-- Same RLS posture as every table: enabled, no policies, service-role only.

create table if not exists conventions (
  project_id uuid primary key default '00000000-0000-4000-8000-000000000001'
    references projects(id) on delete cascade,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

alter table conventions enable row level security;

-- ============ 0013_trend_radar.sql ============
-- 0013: the trend radar - hype-window guide ideas with their own approval gate.
--
-- suggestions.source records which automation queued an idea: 'research' (the
-- weekly run - also the default, so every existing row keeps its meaning) or
-- 'trend-scan' (the Mon/Thu hype scan). Trend ideas get their own approval
-- flag because their value decays in days: with auto_trend on, the scan's
-- single best find approves itself and the daily builder ships it FIRST
-- (newest-first inside a 14-day freshness window - see the build-guide
-- instructions); off, trend ideas wait as pending like everything else.
-- Default true matches 0011's posture (existing projects run auto today).
--
-- projects.last_trend_scan_at lets the scheduled scan skip itself when a
-- manual Scan-now already ran within the last 48 hours; the scan stamps it
-- via the record_trend_scan MCP tool.

alter table suggestions
  add column if not exists source text not null default 'research';
-- The suggestions_source_check constraint deliberately lives in 0014, NOT
-- here, even though this migration introduced the column.
--
-- setup.sql concatenates every migration and is REPLAYED IN FULL on every
-- docker-stack boot (see migrations-vanilla-postgres.yml). Unlike
-- `add column if not exists`, a standalone `add constraint ... check` re-runs
-- and re-validates EVERY existing row each replay - so a narrower
-- intermediate vocabulary here becomes a landmine the moment a later
-- migration widens it. This migration used to add
-- check (source in ('research', 'trend-scan')); 0014 then widened it to
-- include 'manual'. Any database with a single manual idea in it therefore
-- failed to replay setup.sql at THIS line - i.e. every self-host stack whose
-- owner had ever used the dashboard's Add-idea form stopped booting
-- (2026-07-27).
--
-- RULE: when a later migration widens a check constraint, the earlier
-- narrower version must not survive in the replayed history. Only the final
-- vocabulary is applied (0014), which every legal row satisfies by
-- definition.

alter table projects
  add column if not exists auto_trend boolean not null default true,
  add column if not exists last_trend_scan_at timestamptz;

-- ============ 0014_manual_queue.sql ============
-- 0014: manual ideas + a visible, owner-controlled build queue.
--
-- suggestions.source gains 'manual': ideas the owner typed themselves (via
-- the dashboard's Add-idea form or an explicit ask in Claude Code). Manual
-- ideas land already approved - the owner wrote them, there is nothing to
-- gate.
--
-- suggestions.queue_position makes the build order explicit and owner-owned.
-- Semantics (all consumers sort in JS so pre-migration deploys keep working):
--   - lowest position builds next; rows with NULL queue FIFO by created_at
--     AFTER every positioned row.
--   - a dashboard reorder rewrites the whole group (guides vs tools are
--     separate lists) to dense 1..n.
--   - "front" placement (trend approvals, manual do-this-next adds) writes
--     min(position) - 1, so it beats everything already positioned.

alter table suggestions
  add column if not exists queue_position int;

-- This is the ONLY place suggestions_source_check is established (0013 added
-- the column but deliberately leaves the constraint to here - see its
-- comment). setup.sql replays the whole history on every docker boot, and a
-- standalone `add constraint ... check` re-validates every existing row, so
-- the replayed history must contain exactly one, final vocabulary.
-- WIDENING THIS LATER: edit the list HERE rather than adding the new value
-- in a new migration, otherwise this line becomes the landmine 0013 was.
alter table suggestions drop constraint if exists suggestions_source_check;
alter table suggestions
  add constraint suggestions_source_check
  check (source in ('research', 'trend-scan', 'manual'));

-- ============ 0015_site_launched_at.sql ============
-- 0015: age-based publishing pace.
--
-- projects.site_launched_at is when the SITE went live - not when the project
-- was added to DispatchSEO. It drives the publishing-pace tiers (pacing.ts):
-- young sites publish slower, established sites ramp up to daily. Backfilled
-- from created_at (the best guess we have); the owner can correct it on the
-- Settings page.

-- The backfill runs ONLY when this migration actually adds the column.
--
-- setup.sql concatenates every migration and the docker stack REPLAYS it in
-- full on every boot. An unconditional `update` here therefore re-ran forever:
-- every restart reset every project's site_launched_at back to created_at,
-- silently discarding BOTH the owner's Settings correction and the RDAP
-- domain-registration date createProjectCore seeds at creation - so an
-- established site kept reverting to "joined DispatchSEO today" and the
-- Journey/site-age readout lied after each reboot (2026-07-27).
--
-- Same replay rule as 0013/0014: a statement that rewrites EXISTING rows must
-- be gated on the schema change it belongs to, or it becomes a landmine that
-- fires on every boot. `add column if not exists` is self-guarding; a bare
-- `update` is not.
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'projects'
      and column_name = 'site_launched_at'
  ) then
    alter table projects
      add column site_launched_at timestamptz not null default now();
    update projects set site_launched_at = created_at;
  end if;
end $$;

-- ============ 0016_trend_topics.sql ============
-- 0016: the two-stage trend radar. Stage 1 (Scan now) sweeps the niche and
-- queues trending SUBJECTS as trend_topics rows - "codex vs claude code",
-- not finished guide ideas. Stage 2 fires when the owner picks a topic
-- (Get takes): a second workflow expands that one topic into 3-5 concrete
-- guide angles, which land as pending suggestions linked back to the topic
-- via suggestions.trend_topic_id. The owner then queues or builds the takes
-- they like. Splitting the pipeline this way also splits the cost: the sweep
-- is cheap, and deep validation only runs on subjects the owner chose.
--
-- projects.trend_scan_requested_at backs the Scan-now cooldown (30 min):
-- last_trend_scan_at stamps when a scan FINISHES (record_trend_scan), so a
-- separate request stamp is needed to block double-fires while one is still
-- running. trend_topics.expand_requested_at plays the same role per topic.

create table if not exists trend_topics (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null default '00000000-0000-4000-8000-000000000001'
    references projects(id) on delete cascade,
  title text not null,
  -- { why_now, signals[], sources[] } - the hype evidence from the sweep.
  evidence jsonb,
  -- new: waiting for the owner to pick or dismiss it
  -- expanding: Get takes fired, the expand workflow is running
  -- expanded: takes are on the radar as pending suggestions
  -- dismissed: the owner passed (or the scan aged it out after 14 days)
  status text not null default 'new'
    check (status in ('new', 'expanding', 'expanded', 'dismissed')),
  expand_requested_at timestamptz,
  expanded_at timestamptz,
  created_at timestamptz not null default now()
);

-- One radar row per subject per project - a re-scan that finds the same
-- subject again must not duplicate it (the scan dedupes by title too; this
-- is the backstop).
create unique index if not exists trend_topics_project_title
  on trend_topics (project_id, lower(title));

-- Same posture as every operational table: RLS on, zero policies - only the
-- service-role key can touch it.
alter table trend_topics enable row level security;

-- Takes remember which subject they came from, so the Trends page can group
-- them under their topic card. Pre-topic trend suggestions keep null and
-- render in their own legacy block.
alter table suggestions
  add column if not exists trend_topic_id uuid references trend_topics(id) on delete set null;

alter table projects
  add column if not exists trend_scan_requested_at timestamptz;

-- ============ 0017_content_surface.sql ============
-- 0017: the content-surface answer from onboarding. "Does the site have a
-- blog or content section?" - 'existing' = yes (content_path_hint optionally
-- says where), 'create' = no, scaffold one during setup, 'detect' = not sure,
-- the agent inspects the repo and decides. The setup workflow treats this as
-- a hint and reconciles it against what the repo actually contains - the
-- repo always wins, and a second content system is never created.
alter table projects
  add column if not exists content_mode text not null default 'detect'
    check (content_mode in ('existing', 'create', 'detect')),
  add column if not exists content_path_hint text;

-- ============ 0018_pipeline_installed.sql ============
-- 0018: explicit pipeline-install completion mark.
-- The install workflow's final step calls the mark_pipeline_installed MCP
-- tool, which stamps this; the Home setup card flips to its green
-- "installed" state on the stamp (with the conventions row kept as a
-- back-compat fallback signal). Additive and nullable - in-flight code that
-- never selects the column keeps working.
alter table projects add column if not exists pipeline_installed_at timestamptz;

-- ============ 0019_content_prefs.sql ============
-- 0019: owner content preferences - the Instructions page's template controls.
-- One JSONB blob per project ({} = untouched defaults): house_rules free text
-- injected into the build playbooks, disabled_archetypes removed from the
-- guide shape rotation, disabled_blocks dropped from the guide skeleton
-- (tldr / comparison_table / visuals / faq). Normalized and validated in
-- src/lib/content-prefs.ts - the column stays schemaless on purpose so new
-- knobs don't need a migration each.
alter table projects
  add column if not exists content_prefs jsonb not null default '{}'::jsonb;

-- ============ 0020_cron_runs.sql ============
-- 0020: cron run log - the "did my install break overnight?" answer.
-- Every cron route records one row per run (ok or failed, with the error
-- strings). The dashboard Home banner and the get_cron_health MCP tool read
-- the latest row per job; failure emails debounce against emailed_at.
-- No project_id on purpose: a run spans all projects (this is a system
-- table, not operational per-project state) - per-project error detail
-- lives inside the errors jsonb as "slug: message" strings.
create table if not exists cron_runs (
  id uuid primary key default gen_random_uuid(),
  job text not null,
  ok boolean not null,
  errors jsonb not null default '[]',
  emailed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists cron_runs_job_created_idx on cron_runs (job, created_at desc);

-- Same posture as every other table: RLS on, zero policies - only the
-- service-role key (server code) can touch it.
alter table cron_runs enable row level security;

-- ============ 0021_login_lockout.sql ============
-- 0021: login brute-force lockout (launch plan step 1, security).
-- One row per source IP. 5 failed password attempts inside 15 minutes lock
-- that IP out for 15 minutes. All mutation goes through the
-- record_login_failure() function so the count stays atomic without Redis -
-- the dashboard is single-user, this only has to beat scripted guessing.
-- Successful login deletes the row. Complements (not replaces) the Vercel
-- WAF rate-limit rule on the login POST.
create table if not exists login_attempts (
  ip text primary key,
  fails int not null default 1,
  first_fail_at timestamptz not null default now(),
  locked_until timestamptz
);

-- Same posture as every other table: RLS on, zero policies - service-role only.
alter table login_attempts enable row level security;

create or replace function record_login_failure(attempt_ip text)
returns timestamptz
language plpgsql
as $$
declare
  result timestamptz;
begin
  -- Expired lock or expired 15-minute window: start the count over.
  delete from login_attempts
    where ip = attempt_ip
      and ((locked_until is not null and locked_until < now())
        or (locked_until is null and first_fail_at < now() - interval '15 minutes'));

  insert into login_attempts (ip, fails, first_fail_at)
  values (attempt_ip, 1, now())
  on conflict (ip) do update set fails = login_attempts.fails + 1;

  update login_attempts
    set locked_until = now() + interval '15 minutes'
    where ip = attempt_ip and fails >= 5 and locked_until is null;

  select locked_until into result from login_attempts where ip = attempt_ip;
  return result;
end;
$$;

-- ============ 0022_waitlist.sql ============
-- Cloud waitlist signups from the public landing page (and the MCP parity
-- tool). Deliberately NOT project-scoped: an email on the waitlist belongs to
-- the cloud business, not to any tenant, so this table carries no project_id.
-- RLS on with zero policies, same as every other table - only the
-- service-role key touches it.

create table if not exists waitlist_signups (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  source text not null default 'landing',
  created_at timestamptz not null default now()
);

alter table waitlist_signups enable row level security;

-- ============ 0023_gsc_oauth.sql ============
-- 0023: per-project Google OAuth refresh token (launch plan step 3).
-- The dashboard's "Connect Google Search Console" button stores the OAuth
-- refresh token here (AES-256-GCM via crypto.ts, same posture as
-- serpapi_key / dataforseo_password). This is the seed of the cloud GSC
-- flow; the service-account path keeps working unchanged - OAuth is an
-- alternative connection, not a replacement. Additive and nullable.
alter table projects add column if not exists gsc_oauth_refresh_token text;

-- ============ 0024_waitlist_rate_limit.sql ============
-- 0024: waitlist per-IP rate limit (pre-launch security pass).
-- The landing waitlist form is the only unauthenticated write in the app; the
-- honeypot stops dumb bots but nothing stopped a scripted flood from filling
-- waitlist_signups and firing one Resend email per fresh address. Same shape
-- as 0021's login lockout: an atomic Postgres counter, 5 attempts per IP per
-- hour, code fails OPEN if this migration has not run yet.
create table if not exists waitlist_attempts (
  ip text primary key,
  attempts int not null default 1,
  window_start timestamptz not null default now()
);

-- Same posture as every other table: RLS on, zero policies - service-role only.
alter table waitlist_attempts enable row level security;

-- Returns true if this attempt is within the limit, false if the IP is over it.
create or replace function record_waitlist_attempt(attempt_ip text)
returns boolean
language plpgsql
as $$
declare
  current_attempts int;
begin
  delete from waitlist_attempts
    where ip = attempt_ip and window_start < now() - interval '1 hour';

  insert into waitlist_attempts (ip) values (attempt_ip)
  on conflict (ip) do update set attempts = waitlist_attempts.attempts + 1;

  select attempts into current_attempts from waitlist_attempts where ip = attempt_ip;
  return current_attempts <= 5;
end;
$$;

-- ============ 0025_ai_visibility.sql ============
-- 0025: AI visibility (GEO) - for a tracked query, does an AI answer exist,
-- and is this project's domain cited in it? Two writers share the table:
--   - the daily-ranks cron parses Google's AI Overview out of the same SERP
--     pull that checks rankings (engine 'google_ai_overview'), so Google AI
--     data costs nothing beyond the rank check the project already pays for;
--   - the agent's geo-scan workflow samples answer engines on the user's own
--     subscription and writes results via record_ai_citations (engine
--     'claude' today; 'chatgpt' / 'perplexity' / 'gemini' reserved).
-- Append-only snapshots (like rank_checks) so the dashboard can draw a trend.
create table if not exists ai_snapshots (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null default '00000000-0000-4000-8000-000000000001'
    references projects(id) on delete cascade,
  engine text not null,
  query text not null,
  has_ai_answer boolean not null default false,
  cited boolean not null default false,
  cited_url text,
  -- Verbatim answer snippet: the dashboard shows the actual AI text behind
  -- the number, which is what makes the metric feel real.
  answer_excerpt text,
  -- Every source the answer cited: [{domain, url, title}]. Powers the
  -- "cited instead of you" gap list.
  citations jsonb not null default '[]'::jsonb,
  checked_at timestamptz not null default now()
);

create index if not exists ai_snapshots_project_idx
  on ai_snapshots (project_id, engine, checked_at desc);

-- Same posture as every other table: RLS on, zero policies - service-role only.
alter table ai_snapshots enable row level security;

-- ============ 0026_instance_settings.sql ============
-- First-boot setup wizard (the /setup claim screen). One row max: the
-- instance's dashboard password (scrypt hash) and its generated cron secret.
-- Classic installs that set DASHBOARD_PASSWORD / CRON_SECRET env never write
-- here - env always wins at read time, so applying this to an existing
-- deployment changes nothing.
--
-- No project_id on purpose: this is the door to the whole instance, not
-- tenant state. The `id boolean primary key check (id)` trick caps the table
-- at a single row and makes the claim race safe - the second claimer hits a
-- primary-key conflict instead of silently overwriting the first.
create table if not exists instance_settings (
  id boolean primary key default true check (id),
  dashboard_password_hash text not null,
  cron_secret text not null,
  claimed_at timestamptz not null default now()
);

alter table instance_settings enable row level security;

-- ============ 0027_reliability.sql ============
-- Reliability package (2026-07-20 audit): make the first-boot claim carry
-- everything a self-hosted instance needs so nothing depends on undocumented
-- env vars, and give stuck builds a recoverable timestamp.
--
-- instance_settings.app_url: the instance's own public URL, captured from the
-- claim request. getPipelinePack() bakes it into every connected repo's
-- workflows; before this column, self-hosted deploys silently fell back to
-- the cloud domain and shipped pipelines that phoned the wrong backend.
-- instance_settings.enc_key: auto-generated secrets-encryption key, so the
-- onboarding "connect DataForSEO/SerpApi" path works with zero manual env
-- setup (DATAFORSEO_ENC_KEY env still wins when set; existing encrypted rows
-- keep decrypting with whichever key wrote them).
-- suggestions.started_at: stamped when a build marks a suggestion
-- in_progress; the hourly recovery sweep reverts rows stuck past the
-- workflow's own 45-minute timeout back to approved so a crashed build can
-- never strand the queue.

alter table instance_settings add column if not exists app_url text;
alter table instance_settings add column if not exists enc_key text;

alter table suggestions add column if not exists started_at timestamptz;

-- ============ 0028_auto_approve_tools.sql ============
-- 0028: separate auto-approval toggle for TOOL ideas.
--
-- auto_approve (0011) now means guides only. Tools were "approve-idea-first"
-- by instruction-layer fiat with no flag behind it; this column makes that a
-- real toggle. Default true so auto-mode projects go hands-off on tools too
-- (the auto preset = everything on); the semi preset sets it false. Enforcement
-- stays with the MCP's update_suggestion pending-coercion gate - agent tool
-- approvals land pending when this is off. Auto-approved tools do NOT fire the
-- instant build dispatch (owner approvals do); they wait for the weekly
-- tool-builder sweep, keeping the one-tool-a-week cadence.

alter table projects
  add column if not exists auto_approve_tools boolean not null default true;

-- ============ 0029_gsc_service_account_in_db.sql ============
-- 0029: GSC service-account JSON stored in the DB, encrypted (enc:v1:...),
-- so self-hosters connect Search Console entirely from the onboarding wizard
-- - paste the key file, verified on the spot - instead of editing .env and
-- restarting. The env var GSC_SERVICE_ACCOUNT_JSON still wins when set
-- (classic installs, Vercel deployments); the DB copy is the fallback.
-- Single-row instance_settings, same posture as 0026/0027.

alter table instance_settings add column if not exists gsc_service_account_json text;

-- ============ 0030_wizard_owns_setup.sql ============
-- 0030: the wizard owns the whole setup ("suffer once, then it's done").
--
-- gh_merge_token: the GitHub token behind one-tap merge, stored encrypted
-- (enc:v1:...) so the wizard connects it in-browser like the GSC key (0029)
-- - no .env edit, no restart. Env GH_MERGE_TOKEN still wins when set.
--
-- onboarding_screen: where the wizard last stood for a project, so closing
-- the tab (or a stuck terminal) resumes the wizard at the same screen
-- instead of restarting at step 1. Values are the wizard's screen ids.

alter table instance_settings add column if not exists gh_merge_token text;
alter table projects add column if not exists onboarding_screen text;

-- ============ 0031_cloud_users.sql ============
-- 0031: cloud accounts foundation. Adds project ownership (which Supabase
-- Auth user a project belongs to - null on self-host installs, where there
-- are no users) and the subscriptions table billing will fill in. Additive
-- and zero-downtime like every migration.
--
-- Self-host safety: `auth.users` only exists on Supabase. The columns are
-- added everywhere; the foreign keys attach inside a DO block that first
-- checks the auth schema exists - vanilla Postgres (the docker stack's
-- bundled database) skips them, Supabase gets the identical constraints.
-- First docker install after the unguarded version shipped failed with
-- 'schema "auth" does not exist'; this guard is what makes the header's
-- "applies harmlessly on self-host" claim actually true.

alter table projects
  add column if not exists owner_user_id uuid;

create index if not exists projects_owner_user_id_idx on projects (owner_user_id);

-- One row per user, upserted by billing webhooks. Tier limits are stored
-- denormalized (sites_limit/keywords_limit) so enforcement never needs the
-- provider's API on the hot path.
create table if not exists subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null,
  provider text not null default 'polar',
  provider_customer_id text,
  provider_subscription_id text,
  tier text not null default 'starter',
  status text not null default 'inactive',
  sites_limit integer not null default 1,
  keywords_limit integer not null default 100,
  current_period_end timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists subscriptions_user_id_idx on subscriptions (user_id);

-- Same posture as every operational table: RLS on, zero policies - only the
-- service-role key (server code) touches it.
alter table subscriptions enable row level security;

-- Supabase-only: reference auth.users where it exists. Constraint names
-- match what the earlier inline `references` produced, so re-running this
-- on a database that already has them is a no-op.
do $$
begin
  if exists (
    select 1 from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'auth' and c.relname = 'users'
  ) then
    if not exists (select 1 from pg_constraint where conname = 'projects_owner_user_id_fkey') then
      alter table projects
        add constraint projects_owner_user_id_fkey
        foreign key (owner_user_id) references auth.users (id) on delete set null;
    end if;
    if not exists (select 1 from pg_constraint where conname = 'subscriptions_user_id_fkey') then
      alter table subscriptions
        add constraint subscriptions_user_id_fkey
        foreign key (user_id) references auth.users (id) on delete cascade;
    end if;
  end if;
end $$;

-- ============ 0032_builder_heartbeat.sql ============
-- 0032: the builder's heartbeat. The in-stack builder polls
-- /api/builder/jobs every ~10 minutes; stamping each claiming poll gives
-- the UI a verifiable "automatic builds are on" signal - the wizard
-- finale flips its step green off it, and Home shows a setup card until
-- the first check-in (an unlocked dashboard with a dead builder was the
-- silent-failure mode this closes). Plain column, vanilla-Postgres safe.

alter table instance_settings
  add column if not exists builder_last_seen_at timestamptz;

-- ============ 0033_page_liveness.sql ============
-- 0033: truthful "published" state for pages.
--
-- log_page is called when a guide's PR OPENS (the builder can't know when the
-- merge lands), but the dashboard read that row as "live on the site". When a
-- PR stalls unmerged - 2026-07-23: a pack update clobbered an adapted
-- auto-merge gate and a green guide PR sat parked - the Guides screen showed
-- a published guide whose URL 404'd. Split the two states:
--
--   live_at          first time the URL was verified serving HTTP 200
--                    (null = logged but not yet seen live - "awaiting publish")
--   live_checked_at  last verification attempt, so pending pages are probed
--                    with backoff instead of on every render
--
-- Existing rows predate verification and have been listed (and indexed) for a
-- while - presume them live so no established install regresses to a wall of
-- "awaiting publish" (a site whose WAF blocks our checker must not look
-- broken). New rows start null and get stamped by the first successful check.
-- The presume-live backfill runs ONLY on the apply that adds the column.
--
-- setup.sql concatenates every migration and the docker stack REPLAYS it in
-- full on every boot, so `where live_at is null` was NOT a sufficient guard:
-- null is also the legitimate steady state of a page that has been logged but
-- is not live yet (PR still open, or the checker hasn't seen a 200). Every
-- restart therefore stamped exactly those pages as live - reintroducing, on a
-- schedule, the precise lie this migration was written to end (2026-07-27).
--
-- Same replay rule as 0013/0014/0015: a statement that rewrites EXISTING rows
-- must be gated on the schema change it belongs to.
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'pages'
      and column_name = 'live_at'
  ) then
    alter table pages add column live_at timestamptz;
    update pages set live_at = coalesce(published_at, created_at);
  end if;
end $$;

alter table pages add column if not exists live_checked_at timestamptz;

-- ============ 0034_github_app.sql ============
-- 0034: GitHub App install core. Adds the columns the App's install flow
-- (src/app/api/github/install/{start,callback}) writes: the installation id
-- GitHub assigns when the owner installs/updates the App on a repo or org,
-- and when that happened. Both are plain columns - no auth/storage objects
-- involved - so unlike 0031 this needs no DO-guard to stay vanilla-Postgres
-- safe; it applies identically on Supabase and the docker stack's setup.sql.
--
-- Auth plumbing only: the App does not yet replace github.ts's PAT-based
-- calls (mergePr, dispatchToolBuild, ...) - that swap, plus webhook handling
-- and per-project secret storage, are later steps.

alter table projects add column if not exists github_installation_id bigint;
alter table projects add column if not exists github_app_installed_at timestamptz;
create index if not exists projects_github_installation_id_idx on projects (github_installation_id);

-- ============ 0035_dataforseo_usage.sql ============
-- 0035: bundled DataForSEO on cloud, per-tier metering. Platform credentials
-- (DATAFORSEO_PLATFORM_LOGIN/PASSWORD) bill paid cloud projects that never
-- connected their own DataForSEO account; this ledger is what keeps that
-- spend inside each owner's tier budget. One row per (project, day,
-- endpoint), incremented atomically through record_dataforseo_usage so
-- concurrent calls never race a read-modify-write - same pattern as
-- record_login_failure in 0021_login_lockout.sql. Only references `projects`
-- (no auth schema), so no DO-block guard is needed for vanilla Postgres.
create table if not exists dataforseo_usage (
  project_id uuid not null references projects (id) on delete cascade,
  day date not null,
  endpoint text not null,
  calls integer not null default 0,
  cost_microusd bigint not null default 0,
  updated_at timestamptz not null default now(),
  primary key (project_id, day, endpoint)
);

-- Same posture as every other table: RLS on, zero policies - service-role only.
alter table dataforseo_usage enable row level security;

create or replace function record_dataforseo_usage(
  p_project_id uuid,
  p_day date,
  p_endpoint text,
  p_calls integer,
  p_cost_microusd bigint
)
returns void
language plpgsql
as $$
begin
  insert into dataforseo_usage (project_id, day, endpoint, calls, cost_microusd, updated_at)
  values (p_project_id, p_day, p_endpoint, p_calls, p_cost_microusd, now())
  on conflict (project_id, day, endpoint) do update
    set calls = dataforseo_usage.calls + excluded.calls,
        cost_microusd = dataforseo_usage.cost_microusd + excluded.cost_microusd,
        updated_at = now();
end;
$$;

-- ============ 0036_install_progress.sql ============
-- 0036: agent-reported install progress for the wizard finale's checklist.
-- Installs run 10-60 minutes and the owner watches a mostly-dark screen; the
-- mark_install_step MCP tool merges {step: ISO timestamp} into this column
-- the moment the agent finishes each part, and the finale ticks the matching
-- row. Only the parts with no backend-visible artifact live here (workflows
-- written, stack adapted, repo settings, content home, site facts, research
-- kicked off) - derived signals (canary, site profile, the unlock stamp)
-- stay authoritative for their rows. Plain jsonb, vanilla-Postgres safe.

alter table projects add column if not exists install_progress jsonb not null default '{}'::jsonb;

-- ============ 0037_builder_claude_token.sql ============
-- 0037: the in-stack builder's Claude Code OAuth token, wizard-owned.
-- Same "suffer once in the browser, never touch .env" pattern as the GSC key
-- (0029) and the GitHub merge token (0030): the owner pastes their
-- sk-ant-oat... token on the dashboard's automatic-builds step, it's stored
-- encrypted (enc:v1:...) here, and /api/builder/jobs hands it to the builder
-- container in its poll feed - exactly how the merge token already reaches
-- it. Removes the last step that made owners hunt for the install folder and
-- edit .env by hand. The container's own CLAUDE_CODE_OAUTH_TOKEN env (set in
-- docker-compose from .env) still wins when present, so classic installs are
-- unchanged. Single-row instance_settings, vanilla-Postgres safe.

alter table instance_settings add column if not exists builder_claude_token text;

-- ============ 0038_rls_owner_policies.sql ============
-- 0038: RLS policies as a defense-in-depth backstop behind the app-code
-- project_id/owner_user_id scoping (projects.ts, tenant-guard.ts). Every
-- caller today is trusted server code on the service-role key, which bypasses
-- RLS regardless of policy count - so these policies are currently inert, not
-- a fix for a live hole. They exist so that if a client-side/anon-key
-- Supabase path is ever added by mistake, a missed project_id filter in app
-- code still can't leak another owner's rows.
--
-- Supabase-only, same guard as 0031's auth.users FKs: vanilla Postgres (the
-- docker stack) has no auth schema/auth.uid(), so the whole block is a no-op
-- there - self-host isolation is unaffected either way (single owner, no
-- per-row ownership to enforce). Idempotent: checked against pg_policies
-- before creating, safe to re-run (setup.sql applies every migration twice).

do $$
declare
  tbl text;
begin
  if exists (
    select 1 from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'auth' and c.relname = 'users'
  ) then
    -- security definer so the policy check itself doesn't recurse through
    -- projects' own RLS; search_path pinned so it can't be shadowed.
    execute $sql$
      create or replace function project_owned_by_caller(pid uuid)
      returns boolean
      language sql
      stable
      security definer
      set search_path = public
      as $fn$
        select exists (
          select 1 from projects p
          where p.id = pid and p.owner_user_id = auth.uid()
        );
      $fn$;
    $sql$;

    if not exists (
      select 1 from pg_policies
      where schemaname = 'public' and tablename = 'projects' and policyname = 'owner_can_access'
    ) then
      execute 'create policy owner_can_access on projects for all using (owner_user_id = auth.uid()) with check (owner_user_id = auth.uid())';
    end if;

    if not exists (
      select 1 from pg_policies
      where schemaname = 'public' and tablename = 'subscriptions' and policyname = 'owner_can_access'
    ) then
      execute 'create policy owner_can_access on subscriptions for all using (user_id = auth.uid()) with check (user_id = auth.uid())';
    end if;

    -- Every table scoped by project_id (pages.ts / active-project.ts's tenant
    -- axis) - kept as an explicit list rather than introspected so a future
    -- table is a deliberate addition here, not a silent gap.
    for tbl in select unnest(array[
      'pages', 'keywords', 'rank_checks', 'suggestions', 'gsc_stats',
      'backlink_prospects', 'playbook_status', 'site_profile',
      'domain_ratings', 'conventions', 'trend_topics', 'ai_snapshots',
      'dataforseo_usage'
    ])
    loop
      if not exists (
        select 1 from pg_policies
        where schemaname = 'public' and tablename = tbl and policyname = 'owner_can_access'
      ) then
        execute format(
          'create policy owner_can_access on %I for all using (project_owned_by_caller(project_id)) with check (project_owned_by_caller(project_id))',
          tbl
        );
      end if;
    end loop;
  end if;
end $$;

-- ============ 0039_cron_claim_marker.sql ============
-- Distinguishes a builder job "handed out" from one that actually finished.
-- /api/builder/jobs logs a claim row the moment it hands a job to the
-- in-stack builder container, so the next poll doesn't hand out the same
-- job twice; the container is supposed to overwrite it with the real
-- outcome via /api/cron/deploy-check. Without this column that claim row is
-- indistinguishable from a genuine success, so a builder that dies before
-- reporting back (bad token, crash, container restart) leaves the job
-- silently "done" for its full cadence window - up to 156h for research
-- (2026-07-27: a stale in-memory GitHub token handed the builder a null
-- token at the exact moment it claimed research/build-guide/geo-scan; all
-- three then sat "complete" for nearly a week with nothing having run).
alter table cron_runs add column if not exists claimed_only boolean not null default false;

-- ============ 0040_pipeline_verified.sql ============
-- mark_pipeline_installed's backend verification result (verifyPipelinePrereqs)
-- was only ever returned in the ephemeral MCP tool-call response the agent
-- sees once - never persisted, so the dashboard's "Pipeline verified" step
-- could only ever show "done" the instant pipeline_installed_at was set, with
-- no way to later distinguish a real backend-checked pass from the no-op that
-- happens whenever no merge/dispatch token is configured (a state the wizard's
-- own "Skip - I'll merge on GitHub" button leads owners into). Persisting it
-- lets the UI tell those two states apart instead of claiming "Verified" for
-- both.
alter table projects add column if not exists pipeline_verified boolean;

-- ============ 0041_backlink_status_changed.sql ============
-- backlink_prospects had no way to tell "contacted yesterday" from "contacted
-- 6 months ago with no reply" - update_backlink_prospect only ever touched
-- status, so an outreach could go stale forever with zero visibility on the
-- Backlinks dashboard (2026-07-27 audit). Stamp every status transition so
-- the dashboard can flag a prospect stuck in one status too long.
alter table backlink_prospects add column if not exists status_changed_at timestamptz;

-- ============ 0042_serp_tasks.sql ============
-- 0042: SERP task-queue ledger.
--
-- Rank checks moved from DataForSEO's live endpoints to its standard task
-- queue (~70% cheaper at the depths we use, and billing is flat by requested
-- depth instead of by pages returned). The daily-ranks cron POSTs tasks and
-- records them here; the serp-collect cron fetches finished tasks, writes
-- rank_checks / AI-visibility rows, and stamps collected_at. A row with
-- collected_at NULL is in flight; error records a task that came back failed
-- (or was abandoned by the queue) so the collector can report it loudly.
--
-- Plain vanilla-Postgres objects only - no Supabase-specific references, so
-- the docker stack's setup.sql replay needs no guard block.

create table if not exists serp_tasks (
  id text primary key,                -- DataForSEO task id
  project_id uuid not null default '00000000-0000-4000-8000-000000000001'
    references projects(id) on delete cascade,
  keyword_id uuid references keywords(id) on delete cascade,
  keyword text not null,
  -- rank    = daily depth-30 check of a keyword recently seen in the top 30
  -- sweep   = weekly full-depth check (+ AI Overview) of every tracked keyword
  -- confirm = same-day full-depth recheck after a rank task lost the domain
  purpose text not null,
  depth int not null,
  posted_at timestamptz not null default now(),
  collected_at timestamptz,
  error text
);

-- The collector's hot path: pending tasks per project, oldest first.
create index if not exists serp_tasks_pending_idx
  on serp_tasks (project_id, posted_at)
  where collected_at is null;

-- Service-role only, like every operational table (RLS on, zero policies).
alter table serp_tasks enable row level security;

-- ============ 0043_suggestion_keyword_unique.sql ============
-- 0043: one keyword, one live idea.
--
-- Both insert paths into suggestions (the MCP propose_suggestion tool and the
-- dashboard's Add idea form) inserted unconditionally; the only dedupe that
-- existed was a line in the agent instructions telling each research run to
-- pull the queue first. A run that checked only one status re-proposed an
-- already-approved keyword, the owner approved the second copy from Home, and
-- the queue listed the same guide twice (2026-07-29, "claude code hooks") -
-- two builders, two PRs, one keyword competing with itself.
--
-- src/lib/suggestion-dedupe.ts is the readable check both callers now run;
-- this index is the race-proof backstop under it. Scoped to LIVE rows only:
-- rejected ideas and shipped guides are history, and a keyword may legitimately
-- be revisited once its first guide is done (the app answers that case with a
-- note rather than a block).
--
-- Plain vanilla-Postgres objects only - no Supabase-specific references, so
-- the docker stack's setup.sql replay needs no guard block. lower()/btrim()
-- are IMMUTABLE, so both are legal in an index expression.

create unique index if not exists suggestions_live_keyword_idx
  on suggestions (project_id, type, lower(btrim(primary_keyword)))
  where status in ('pending', 'approved', 'in_progress') and primary_keyword is not null;

-- ============ 0044_project_agent.sql ============
-- Which coding agent drives a project's builders.
--
-- Until now "the agent" meant Claude Code everywhere - the CI workflows, the
-- docker builder, the connect command, the setup script. Adding a second agent
-- (Codex) needs the choice stored per PROJECT, because one owner can run
-- several sites and the GitHub-Actions path already keeps its credential per
-- repo. Defaults to 'claude' so every existing row keeps behaving exactly as it
-- does today, and so does any in-flight write that predates this column.
alter table projects add column if not exists agent text not null default 'claude';

-- Constrain the values, but only once - re-running this file (the docker stack
-- replays the concatenated setup.sql on every boot) must not fail on an
-- already-present constraint. A plain ADD CONSTRAINT has no IF NOT EXISTS.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'projects_agent_check'
  ) then
    alter table projects
      add constraint projects_agent_check check (agent in ('claude', 'codex'));
  end if;
end $$;

-- The self-host builder credential, one per agent.
--
-- 0037 added a single builder_claude_token at INSTANCE level, which the
-- /api/builder/jobs poll feed hands to the container. That is fine while every
-- project uses the same agent, and breaks the moment one stack hosts a Claude
-- project and a Codex project: there is only one credential slot, so one of
-- them silently gets the wrong one. A column per agent keeps the instance-level
-- storage (the docker stack genuinely has one set of credentials) while letting
-- the feed resolve the RIGHT one per job from the project's agent.
--
-- Nullable on purpose: an instance that only ever runs one agent stores only
-- that agent's credential, and the builder already idles politely when the
-- credential it needs is absent.
alter table instance_settings add column if not exists builder_openai_key text;

-- ============ 0045_project_internal_linking.sql ============
-- Whether the guide builder may edit ALREADY-PUBLISHED posts.
--
-- Every builder behaviour up to now has been additive: propose an idea, write a
-- new page, open a PR that only adds files. Internal back-linking is the first
-- thing that reaches back into content the owner already published and shipped
-- - it edits 2-3 existing posts so they link to the new one, which is what
-- turns a pile of posts into a cluster that compounds.
--
-- That is a different trust category from everything else the agent does, so it
-- is opt-in per project and defaults to OFF. An owner who never flips it keeps
-- today's behaviour byte for byte. Do NOT seed this to true for any project
-- here: the docker stack replays the concatenated setup.sql on every boot, so a
-- seeded UPDATE would silently switch the feature on for every self-host
-- install's default project.
alter table projects
  add column if not exists internal_linking boolean not null default false;

comment on column projects.internal_linking is
  'Opt-in: allow the guide builder to edit already-published posts to add internal links back to a new guide. Default false - this is the only agent behaviour that modifies existing published content.';

-- ============ 0046_feedback.sql ============
-- 0046: the product feedback board.
--
-- What the dashboard's /feedback screen is backed by: feature requests written
-- by the people using DispatchSEO, and one vote per person per request so the
-- ordering is theirs rather than the owner's.
--
-- Deliberately NOT project-scoped, which is the one place this table breaks the
-- house rule that every operational table carries a project_id. A feedback
-- board only works if everyone sees the same list: scoping rows to a project
-- would give each tenant a private board of one, which is the thing the feature
-- exists to avoid. project_id survives as nullable ATTRIBUTION - which site the
-- author was looking at when they wrote it - and nothing reads it as a filter.
--
-- The two deployment modes use this differently:
--   CLOUD_MODE   - the full board. Many accounts, so author_user_id is set and
--                  feedback_votes can enforce one vote per account.
--   self-host    - one person, so there is no board to show. The row is still
--                  written (it rate-limits submissions and keeps the text if
--                  the email fails), the UI just says thank you, and the
--                  request is emailed to the DispatchSEO team.
--
-- Plain vanilla-Postgres objects only - no Supabase-specific references, so the
-- docker stack's setup.sql replay needs no guard block. author_user_id is a
-- bare uuid rather than a reference to auth.users for exactly that reason: the
-- auth schema does not exist on a self-hosted vanilla Postgres.

create table if not exists feedback (
  id uuid primary key default gen_random_uuid(),
  -- The request itself. Plain text, always: the app rejects links and markup at
  -- submit time, so nothing here is ever rendered as anything but text.
  title text not null,
  body text not null default '',
  -- open | planned | in_progress | shipped | declined. Free text rather than an
  -- enum so adding a status later is a code change, not a migration.
  status text not null default 'open',
  -- Supabase auth uid in CLOUD_MODE, null on self-host (no accounts there).
  author_user_id uuid,
  -- Kept so the owner can reply to whoever asked; never shown on the board.
  author_email text,
  -- Attribution only - see the note above. ON DELETE SET NULL, not CASCADE:
  -- deleting a site must not delete the feedback that site's owner wrote.
  project_id uuid references projects(id) on delete set null,
  -- The moderation lever. Hidden rows stay in the table (so a re-post from the
  -- same author still trips the duplicate/rate checks) and drop off the board.
  hidden boolean not null default false,
  created_at timestamptz not null default now(),
  status_changed_at timestamptz
);

-- The board's default read: visible rows, newest first. Votes are counted from
-- feedback_votes rather than a denormalized column - at board scale the count
-- is cheap, and a cached integer that drifts from the votes it summarizes is a
-- bug you only notice once the ordering is already wrong.
create index if not exists feedback_visible_idx
  on feedback (created_at desc)
  where hidden = false;

-- One vote per account per request; the primary key IS that rule, so a double
-- click races into a duplicate-key error instead of a second vote.
create table if not exists feedback_votes (
  feedback_id uuid not null references feedback(id) on delete cascade,
  user_id uuid not null,
  created_at timestamptz not null default now(),
  primary key (feedback_id, user_id)
);

-- Counting a person's recent votes (the abuse limiter) reads by user + time.
create index if not exists feedback_votes_user_idx on feedback_votes (user_id, created_at desc);

-- Rate limiting counts a person's recent submissions.
create index if not exists feedback_author_idx on feedback (author_user_id, created_at desc);

-- Service-role only, like every operational table (RLS on, zero policies).
alter table feedback enable row level security;
alter table feedback_votes enable row level security;

-- ============ 0047_subscription_cancel_at_period_end.sql ============
-- Whether this subscription is set to end when the current period does.
--
-- Polar keeps a cancelled-at-period-end subscription at status 'active' (or
-- 'trialing') right up to the last day - the customer paid for the period and
-- keeps it. Only when the period actually ends does it flip to 'canceled'.
-- That is exactly the behaviour we want for access, and it is why the status
-- column alone cannot answer "is this plan ending?": a cancelled plan and a
-- renewing one are both 'active' until the very end.
--
-- Without this column the dashboard has no way to show someone that their
-- cancellation landed, which is the difference between a quiet churn and a
-- support email asking "did it work?". Mirrors Polar's own
-- `cancel_at_period_end` field, written by the webhook on every subscription
-- event and optimistically by the cancel action so the page reflects the click
-- before the webhook arrives.
--
-- Self-host never has a row here (no billing), so this is inert there.
alter table subscriptions
  add column if not exists cancel_at_period_end boolean not null default false;

comment on column subscriptions.cancel_at_period_end is
  'True when the plan is set to end at current_period_end. Status stays active/trialing until then - this is the only signal that a cancellation is pending.';

-- ============ 0048_github_cost_ack.sql ============
-- The third-site GitHub Actions cost acknowledgement.
--
-- Every site's automations run as GitHub Actions in the OWNER's own repo, on
-- the owner's own GitHub account - a cost we never see and never bill. GitHub's
-- free allowance covers roughly two sites; from the third, a private-repo owner
-- either raises their spending limit or their workflows silently pause, which
-- looks exactly like DispatchSEO breaking. The dashboard has warned about this
-- since the add-site dialog shipped, but the notice was dismissible and easy to
-- scroll past, so nobody had to decide anything.
--
-- This column records that the owner has been shown the cost and made a choice.
-- It is per ACCOUNT, not per project (the GitHub allowance belongs to the
-- account), so it lives on the one-row-per-user subscriptions table rather than
-- in a table of its own.
--
-- `github_cost_ack_reason` records WHICH way out they took, because the answers
-- age differently: someone who raised a spending limit stays fine, while
-- "my repos are public" stops being true the day they flip one private.

alter table subscriptions
  add column if not exists github_cost_ack_at timestamptz;

alter table subscriptions
  add column if not exists github_cost_ack_reason text;

-- No default and no backfill, deliberately. A null means "never asked", which
-- is the truth for every existing account - including the ones already past
-- three sites. They get asked the next time they add one, which is the only
-- moment the question is actionable anyway.

-- ============ 0049_install_id.sql ============
-- Anonymous install id for the self-host heartbeat (src/lib/heartbeat.ts).
--
-- A random UUID and nothing else. It exists so the project can answer "how
-- many self-hosted installs are actually running" - a question clone counts
-- and GHCR pulls cannot answer, because neither can tell one machine booting
-- ten times from ten machines booting once. It identifies an INSTALL, never a
-- person: it is not derived from the domain, the owner's email, the tracked
-- keywords or anything else in this database, so it carries no signal beyond
-- "this install was alive today".
--
-- Generated lazily on the first heartbeat rather than at claim time, so
-- installs that were claimed before this migration get one too. Nullable for
-- the same reason, and because DISPATCH_INSTALL_ID in the env wins over it
-- (that is the docker path - start.sh writes one into .env on first boot,
-- which covers stacks that never ran the setup wizard and therefore have no
-- instance_settings row at all).
--
-- The owner can switch the whole thing off with DISPATCHSEO_TELEMETRY=off,
-- in which case this column is written but never read.
alter table instance_settings
  add column if not exists install_id text;

comment on column instance_settings.install_id is
  'Random UUID identifying this install for the anonymous daily heartbeat. Not derived from any tenant data. Unused when DISPATCHSEO_TELEMETRY=off.';

-- ============ 0050_agent_check_open.sql ============
-- Open the agent column to future agents.
--
-- 0044 CHECK-constrained projects.agent to ('claude', 'codex'), which made
-- every new coding agent a migration - and worse, a migration ORDERING trap:
-- a backend that ships a third agent before a self-host or cloud database has
-- run the matching migration turns every set_agent call into a constraint
-- violation. Validation already lives in exactly one app-side place
-- (isSupportedAgent via the registry in src/lib/agents/index.ts, asserted by
-- scripts/agent-golden.mjs against prototype-pollution bypasses), and the
-- column's only writer (setProjectAgent) goes through it - so the database
-- copy of the allow-list was a second source of truth that could only ever
-- drift. Dropped rather than widened.
--
-- DROP CONSTRAINT IF EXISTS is idempotent, so the docker stack's replay of
-- the concatenated setup.sql on every boot passes untouched, and vanilla
-- Postgres needs no guard block.
alter table projects drop constraint if exists projects_agent_check;

-- ============ 0051_domain_rating_history.sql ============
-- Domain-rating history: one row per successful DataForSEO backlinks-summary
-- refresh (weekly per project via the daily-ranks cron, plus the occasional
-- stale-cache refresh from a dashboard render).
--
-- domain_ratings deliberately stores only the LATEST snapshot - progress.ts
-- has carried a "DR movement cannot be derived honestly yet" comment since the
-- weekly strip shipped, because a single-row cache has no yesterday. This
-- table is that missing yesterday: an append-only series the authority
-- surfaces read for "referring domains +N this month", the 5-referring-domains
-- journey milestone, and stagnation nudges. Nothing ever updates or deletes a
-- row; refreshDomainRating appends alongside its upsert of the cache row, and
-- a failed insert is swallowed there (history is an enhancement, never a
-- reason a refresh fails).
--
-- Plain table, no Supabase-only objects - vanilla Postgres (the docker
-- stack's setup.sql replay) takes it unguarded.
create table if not exists domain_rating_history (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade
    default '00000000-0000-4000-8000-000000000001',
  dr int,
  rank int,
  referring_domains int,
  backlinks int,
  spam_score int,
  fetched_at timestamptz not null default now()
);

-- Readers always ask "this project's rows, newest/oldest first".
create index if not exists domain_rating_history_project_fetched_idx
  on domain_rating_history (project_id, fetched_at desc);

-- Same posture as every other table: RLS on, zero policies - only the
-- service-role key (dashboard + MCP server + crons) touches it.
alter table domain_rating_history enable row level security;

-- ============ 0052_refresh_source.sql ============
-- suggestions.source gains 'refresh': update ideas queued by the nightly
-- refresh detector (src/lib/refresh-detect.ts), which finds published guides
-- sitting at position 5-20 for their primary keyword and queues a
-- type:"update" suggestion for the daily builder's UPDATE MODE.
--
-- Same drop-and-re-add dance as 0014 (the constraint's one home): CHECK
-- constraints can't be widened in place, and DROP IF EXISTS keeps the docker
-- stack's setup.sql replay idempotent. Vanilla Postgres needs no guard block.
alter table suggestions drop constraint if exists suggestions_source_check;
alter table suggestions
  add constraint suggestions_source_check
  check (source in ('research', 'trend-scan', 'manual', 'refresh'));

-- ============ 0053_builder_cursor_key.sql ============
-- The instance-level credential slot for Cursor's builder.
--
-- Same shape and same reasoning as 0044's builder_openai_key: the docker stack
-- stores one set of credentials per INSTANCE, and /api/builder/jobs resolves
-- the right one per job from the project's agent, so a stack hosting projects
-- on different agents never hands one of them the wrong credential.
--
-- Lands AHEAD of the feature on purpose. src/lib/agents/index.ts already names
-- this column (cursor's credential.instanceSettingsColumn) and nothing reads it
-- yet, because Cursor is registered with headlessBuilder: false and every
-- caller of builderAgentToken() sits behind a builderAgents() filter. The
-- ordering only matters in one direction: a backend that starts reading the
-- column before a database has it is the failure, migrations here are applied
-- by hand, so the column goes first and waits. Nullable, additive, idempotent -
-- an instance that never runs Cursor leaves it null, which is what an absent
-- credential already means everywhere else.
--
-- Plain ALTER with IF NOT EXISTS: no Supabase-only objects, so the docker
-- stack's replay of the concatenated setup.sql on every boot passes untouched
-- and vanilla Postgres needs no guard block.
alter table instance_settings add column if not exists builder_cursor_key text;

-- ============ 0054_signup_qualifier.sql ============
-- Pre-checkout qualifier answers (cloud only).
--
-- Why this table exists: four paid trials, four losses, none of which ever saw
-- a published article. Two were WordPress sites that hit "Connect GitHub" - a
-- screen no WordPress owner can ever pass - and one of those cancelled inside
-- five minutes with the reason "unused". A fourth had no coding agent and
-- stopped at "Connect your coding agent". Every one of those facts was
-- knowable BEFORE the card was charged: the platform from one HTTP request
-- (src/lib/site-platform.ts), the agent from one question.
--
-- So the answers are collected before checkout and kept, for two jobs:
--   1. Gating: an owner we cannot serve today is told so instead of being
--      charged and walked into a dead end.
--   2. Counting: "how many WordPress owners did we turn away this week" is
--      the number that sizes the audience the WordPress work is being built
--      for. Without a row per attempt, that number does not exist.
--
-- Append-only by design (no unique index on user_id): someone who checks two
-- domains produces two rows, and both are signal. The gate reads the newest
-- row for the user.
--
-- Vanilla-Postgres safe: no auth schema reference outside the guarded DO block
-- at the bottom, so docker's setup.sql replay works on a database that has no
-- Supabase auth at all.

create table if not exists signup_qualifiers (
  id uuid primary key default gen_random_uuid(),
  -- The signed-up cloud user. No FK here - see the guarded block below, which
  -- adds one only where auth.users actually exists.
  user_id uuid not null,
  -- What they typed. Stored raw (bare host, no scheme) so a support question
  -- can be answered from the row alone.
  domain text not null,
  -- Verdict inputs, straight from detectPlatform(): platform + how sure we
  -- were + which signals fired. Keeping the signals makes a wrong call
  -- debuggable months later instead of a mystery.
  platform text not null,
  confidence text,
  signals jsonb not null default '[]'::jsonb,
  -- WordPress specifics when present: version, elementor, seo plugin, whether
  -- /wp-json/ answered, whether it is a decoupled front end.
  wordpress jsonb,
  -- Which AI they said they have. Free text from a fixed option list, not an
  -- enum: the list of agents this product supports changes faster than a
  -- migration cycle, and an unknown value must never reject a write.
  ai_choice text not null,
  -- What we told them: supported | unsupported | unknown, and which publishing
  -- route they would take (repo | wordpress | null).
  verdict text not null,
  route text,
  -- True once this answer let them through to checkout. A row with
  -- proceeded=false is someone we turned away - the churn that did not happen.
  proceeded boolean not null default false,
  created_at timestamptz not null default now()
);

-- The gate reads "newest row for this user", and the weekly count reads
-- "rows in a date range", so both directions are covered by one index.
create index if not exists signup_qualifiers_user_created_idx
  on signup_qualifiers (user_id, created_at desc);
create index if not exists signup_qualifiers_created_idx
  on signup_qualifiers (created_at desc);

-- Same posture as every other table: RLS on, zero policies - service-role only.
alter table signup_qualifiers enable row level security;

comment on table signup_qualifiers is
  'Pre-checkout platform/agent answers. One row per attempt; proceeded=false means we turned them away before charging.';

-- Supabase-only: reference auth.users where that schema exists. Self-host on
-- vanilla Postgres has no auth schema, and this must not break its first boot.
do $$
begin
  if exists (
    select 1 from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'auth' and c.relname = 'users'
  ) then
    if not exists (select 1 from pg_constraint where conname = 'signup_qualifiers_user_id_fkey') then
      alter table signup_qualifiers
        add constraint signup_qualifiers_user_id_fkey
        foreign key (user_id) references auth.users (id) on delete cascade;
    end if;
  end if;
end $$;

-- ============ 0055_wordpress_publishing.sql ============
-- WordPress as a second publishing route, plus the two tables the new
-- article flow needs.
--
-- Until now there was exactly one way for an article to reach a customer's
-- site: open a pull request in their GitHub repo. That works for a code-built
-- site and is impossible to explain to someone whose site was built for them.
-- Two paid trials died at "Connect GitHub" in August 2026, one of them inside
-- five minutes. These columns are the other door.
--
-- Everything here is additive and defaulted, so in-flight code that knows
-- nothing about WordPress keeps writing valid rows: publish_target defaults to
-- 'github', which is exactly what every existing project is.

-- --- projects: where does this site's content go, and how do we get in ------

alter table projects
  add column if not exists publish_target text not null default 'github';

comment on column projects.publish_target is
  'github = open a PR in the repo (the original route). wordpress = post through the site''s own API. manual = we finish the article and hand it over, for an owner who has neither.';

-- The site's base address, kept separately from projects.domain: the WordPress
-- install can live somewhere the public domain does not (a subdirectory, or a
-- different host entirely behind a CDN), and guessing wrong means every write
-- lands nowhere.
alter table projects add column if not exists wp_url text;
alter table projects add column if not exists wp_username text;

-- Encrypted at rest with the same app-level AES-256-GCM used for the
-- DataForSEO password (src/lib/crypto.ts, "enc:v1:" prefix). Never written
-- plaintext, never logged, never returned by an MCP tool. A row written before
-- encryption existed would read back as legacy plaintext, but there are none:
-- this column is born encrypted.
alter table projects add column if not exists wp_app_password text;

alter table projects add column if not exists wp_connected_at timestamptz;

-- Which SEO plugin the site runs (yoast | rankmath | seopress | null), read
-- from the site's own API at connect time. It decides where a meta description
-- has to be written, so caching it here saves a probe on every single publish.
alter table projects add column if not exists wp_seo_plugin text;

-- What the connected WordPress user is actually allowed to do
-- (publish_posts / upload_files / edit_others_posts / edit_posts), captured at
-- connect time. Publishing checks this BEFORE writing rather than discovering
-- mid-flow that the owner connected a Subscriber - the failure then arrives as
-- a setup card with a fix, not as a half-published article.
alter table projects add column if not exists wp_capabilities jsonb;

-- The hour (0-23, site-local) a finished draft is flipped live. Our cron does
-- this, deliberately: WordPress's own scheduler only runs when someone loads a
-- page, so a scheduled post on a quiet site publishes late - WordPress's own
-- docs give a 2pm-scheduled/5pm-live example. Nullable = use the default.
alter table projects add column if not exists publish_hour smallint;

-- --- The site digest: what we know about a site, so their AI need not ------
--
-- Its own table rather than a projects column on purpose. Every projects query
-- selects the full column list, and this blob is a few KB - putting it on the
-- hot tenant-resolution path would tax every cron, every MCP call and every
-- page load to serve something read only when an article is being written.

create table if not exists site_digests (
  project_id uuid primary key default '00000000-0000-4000-8000-000000000001'
    references projects (id) on delete cascade,
  -- The compact summary a chat AI reads INSTEAD of crawling the site itself
  -- (src/lib/site-crawl.ts buildDigest). Budgeted to stay small enough to sit
  -- inside a $20 plan's context without crowding out the article.
  digest jsonb not null default '{}'::jsonb,
  -- Plain-English observations for the owner: pages we could not read, a cap
  -- we hit, a site that served us the same title for every address. Kept
  -- because a digest built from a quarter of a site must say so.
  notes jsonb not null default '[]'::jsonb,
  page_count integer not null default 0,
  -- wp-rest | sitemap | bfs - which door the crawl actually got in through.
  source text,
  crawled_at timestamptz not null default now()
);

alter table site_digests enable row level security;

-- --- Article drafts: the handoff point between their AI and ours -----------
--
-- The customer's own AI writes an article and submits it here. Our server
-- validates it (src/lib/article-validate.ts), finishes it (HTML, internal
-- links, schema, cover) and publishes it. This table is where an article lives
-- between "their AI said it is done" and "it is live on their site", which is
-- also the only place a human can look at it before it goes out.

create table if not exists article_drafts (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null default '00000000-0000-4000-8000-000000000001'
    references projects (id) on delete cascade,
  -- The queued idea this fulfils. Nullable: an owner can ask their AI to write
  -- something that was never in the queue, and refusing that would make the
  -- queue a cage rather than a plan.
  suggestion_id uuid references suggestions (id) on delete set null,

  title text not null,
  slug text not null,
  meta_description text,
  primary_keyword text,
  markdown text not null,
  faq jsonb not null default '[]'::jsonb,
  sources jsonb not null default '[]'::jsonb,
  cover_brief text,

  -- submitted -> rejected | accepted -> finished -> published (or discarded).
  -- rejected is not terminal: the AI reads the reasons and resubmits.
  status text not null default 'submitted',
  -- The full ValidationReport, including every check that failed and the
  -- exact instruction handed back. Kept so "why was my article rejected" is
  -- answerable weeks later, and so rejection rates per client are measurable.
  validation jsonb,

  rendered_html text,
  cover_url text,
  -- WordPress's own post id, so the publish step can flip the draft it made
  -- rather than creating a second one.
  wp_post_id integer,
  published_url text,

  -- Which AI submitted it (claude-ai, chatgpt, claude-code, codex, cursor).
  -- The whole promise of the server-side gate is that quality does not depend
  -- on this value - which is only checkable if it is recorded.
  client_kind text,
  -- What the finishing steps cost US in model spend. Per-article, because a
  -- margin you cannot see is a margin you find out about from a bill.
  cost_usd numeric(10, 4) not null default 0,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- The dashboard lists a project's drafts newest-first; the publisher looks for
-- what is finished and due. Both are covered here.
create index if not exists article_drafts_project_created_idx
  on article_drafts (project_id, created_at desc);
create index if not exists article_drafts_status_idx
  on article_drafts (project_id, status);

-- One live draft per suggestion. Without this, an AI that retries a submission
-- instead of updating one leaves duplicates behind, and the publisher has no
-- way to tell which is the real article. Partial, so discarded and rejected
-- attempts can pile up harmlessly as history.
create unique index if not exists article_drafts_active_suggestion_idx
  on article_drafts (suggestion_id)
  where suggestion_id is not null and status in ('submitted', 'accepted', 'finished', 'published');

alter table article_drafts enable row level security;

-- ============ 0056_jobs.sql ============
-- Background work, off the request path.
--
-- Three things in the new article flow are too slow to do inside an HTTP
-- request and too important to drop: crawling 150 pages of a site, turning an
-- accepted draft into finished HTML with a cover image, and flipping a
-- WordPress draft live at the hour the owner picked. All three now become rows
-- here, and a cron drains them.
--
-- The claim semantics are lifted wholesale from serp_tasks (0042) because that
-- pattern is already proven in this codebase: a row is "still to do" while its
-- finished_at is null, a claim stamps claimed_at so a second worker skips it,
-- and a claim old enough to be abandoned becomes claimable again. No locks, no
-- queue service, no new dependency - the database row IS the lock.
--
-- Deliberately generic (kind + payload) rather than one table per job type:
-- the alternative is three near-identical tables, three drain routes and three
-- sets of the same retry bug.

create table if not exists jobs (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null default '00000000-0000-4000-8000-000000000001'
    references projects (id) on delete cascade,

  -- crawl | finish | publish | verify. Text, not an enum: a new job type must
  -- be a code change, never a migration that has to reach prod before the code
  -- that needs it (migrations here are applied by hand, so code lands first).
  kind text not null,
  payload jsonb not null default '{}'::jsonb,

  -- Not before this moment. Publishing at the owner's chosen hour and retrying
  -- after a failure are the same mechanism: move run_after and let go.
  run_after timestamptz not null default now(),

  -- Claimed but not finished = in flight. A worker that dies leaves this set
  -- and finished_at null, which the drain route treats as reclaimable after a
  -- grace window rather than as a job stuck forever.
  claimed_at timestamptz,
  finished_at timestamptz,
  attempts integer not null default 0,
  -- Last failure, in the worker's own words. Populated even when the job is
  -- later retried successfully, because "this kept failing for six hours and
  -- then worked" is the shape of a problem worth seeing.
  error text,

  created_at timestamptz not null default now()
);

-- The drain query is "what is due for anyone", so the index leads with the
-- pending predicate. Partial: finished rows are history and must not bloat the
-- hot path.
create index if not exists jobs_due_idx
  on jobs (run_after, project_id)
  where finished_at is null;

create index if not exists jobs_project_created_idx
  on jobs (project_id, created_at desc);

-- Idempotency. A cron that fires twice, a webhook that retries, an owner who
-- double-clicks: all three must produce ONE job. The key is chosen by the
-- producer (e.g. "publish:<draft-id>", "crawl:<project>:<date>"), and the
-- partial uniqueness means a finished job's key is free to be used again -
-- tomorrow's crawl is not blocked by yesterday's.
alter table jobs add column if not exists idempotency_key text;
create unique index if not exists jobs_pending_key_idx
  on jobs (project_id, kind, idempotency_key)
  where finished_at is null and idempotency_key is not null;

-- Same posture as every other table: RLS on, zero policies - service-role only.
alter table jobs enable row level security;

comment on table jobs is
  'Generic background work queue drained by a cron. finished_at null = still to do; claimed_at set = in flight, reclaimable after a grace window.';

-- ============ 0057_site_link_candidates.sql ============
-- The crawled page inventory, kept apart from the digest it sits next to.
--
-- 0055 gave site_digests one jsonb column, `digest`, described there as "the
-- compact summary a chat AI reads INSTEAD of crawling the site itself" - and
-- that description is load-bearing: it is budgeted to stay small enough to fit
-- inside a $20 ChatGPT or Claude plan's context without crowding out the
-- article being written.
--
-- Internal linking needs something different: the full list of the site's
-- pages with their titles, so the finisher can turn a phrase in a new article
-- into a link to an existing page. That list is an order of magnitude larger
-- than the digest and is read by our own server, never by the customer's AI.
--
-- Folding the two together would have quietly broken the thing the digest
-- exists for. Hence a second column rather than a wrapper object inside the
-- first one.

alter table site_digests
  add column if not exists link_candidates jsonb not null default '[]'::jsonb;

comment on column site_digests.link_candidates is
  'Crawled pages as [{url,title,keywords}] for the finisher to link into. Server-side only - never sent to a customer''s AI, which reads `digest` instead.';

-- ============ 0058_research_notes.sql ============
-- Research a chat session can hand to the next chat session.
--
-- On a coding agent, research and writing happen in one long run and the
-- findings live in its context. A chat app has neither the window nor the
-- continuity: a $20 plan cannot hold a SERP sweep, three competitor pages and
-- a finished article in one conversation, and the owner closes the tab anyway.
-- Splitting the work in two - one chat researches, another writes - is the
-- only shape that fits, and it needs somewhere to put the findings in between.
--
-- The notes are free-form jsonb because the shape is the AI's business, not
-- ours: SERP observations, competitor gaps, an outline, an angle. Our side
-- stores and returns them; nothing here parses them.

create table if not exists research_notes (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null default '00000000-0000-4000-8000-000000000001'
    references projects (id) on delete cascade,
  -- Which queued idea this research is for. Nullable: an owner can ask their
  -- AI to look into something that was never in the queue, and a note with
  -- nowhere to attach is still worth keeping.
  suggestion_id uuid references suggestions (id) on delete cascade,
  notes jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- One live note per idea, so a second research pass REPLACES the first rather
-- than leaving the writing session to guess which of two versions is current.
--
-- NOT a partial index (`where suggestion_id is not null`), which is what this
-- started as: PostgREST's upsert issues ON CONFLICT (project_id,
-- suggestion_id), and Postgres will not use a partial index as the arbiter for
-- that unless the statement carries the same predicate - so every upsert
-- failed with "no unique or exclusion constraint matching the ON CONFLICT
-- specification". A full index does the same job here anyway: Postgres treats
-- NULLs as distinct, so the unattached notes above are each their own row and
-- only the ones tied to an idea are deduped.
create unique index if not exists research_notes_suggestion_idx
  on research_notes (project_id, suggestion_id);

-- The unattached notes, newest first: what the dashboard and get_research_notes
-- list when no suggestion is named.
create index if not exists research_notes_project_created_idx
  on research_notes (project_id, created_at desc);

alter table research_notes enable row level security;

-- ============ 0059_blocked_setup_is_live.sql ============
-- blocked_setup joins the statuses that make a draft "live".
--
-- 0055's one-live-draft-per-suggestion index enumerated the live statuses as
-- submitted/accepted/finished/published - and missed blocked_setup, the draft
-- that passed the gate, was rendered, and is parked only because the site has
-- nowhere to publish yet. In every sense that matters it is an accepted
-- article waiting to go out, so while one is parked a second submission for
-- the same idea could slip past the index and become a second live draft -
-- two articles for one idea the moment the owner connects their site. The
-- code-side checks (submit_article's prior-draft lookup and dedupe corpus)
-- were widened in the same change; this brings the constraint itself along.
--
-- Safe to apply on a live database: article_drafts is new (0055, 2026-08-18)
-- and recreating a partial index on it is instant at this size. Vanilla-
-- Postgres safe: no auth schema, nothing Supabase-specific.

drop index if exists article_drafts_active_suggestion_idx;
create unique index if not exists article_drafts_active_suggestion_idx
  on article_drafts (suggestion_id)
  where suggestion_id is not null
    and status in ('submitted', 'accepted', 'blocked_setup', 'finished', 'published');

-- ============ 0060_ai_choice_repo_publishing.sql ============
-- The adaptive wizard and the second publishing route for chat clients.
--
-- Three small additions, all additive and nullable, so in-flight code that
-- knows nothing about them keeps writing valid rows:
--
--   projects.ai_choice        which AI the owner said will do the writing - the
--                             qualifier's answer carried onto the project so the
--                             wizard, the Connect screen and the Home cards can
--                             branch on it instead of asking again. One of the
--                             qualifier's ids: claude-web, chatgpt, claude-code,
--                             codex, cursor (src/lib/qualifier-options.ts).
--                             Null = never said (created before 0060, or outside
--                             the wizard). Distinct from `agent`, which names the
--                             coding agent the repo builders run and has no
--                             value for a chat app.
--   projects.chat_last_seen_at  the last request that arrived on the MCP door
--                             with ?client=chat. This is the "Connected" light
--                             on the wizard's Claude-app step and on /connect:
--                             evidence that the owner's chat app actually
--                             reached us, rather than a button they press to
--                             say so. Stamped at most every ten minutes.
--   article_drafts.pr_*       a draft published through a GitHub repo rather
--                             than WordPress: the pull request our server
--                             opened, the file it committed, and when the PR
--                             merged. Null on the WordPress route.

alter table projects add column if not exists ai_choice text;
alter table projects add column if not exists chat_last_seen_at timestamptz;

comment on column projects.ai_choice is
  'Which AI the owner said will write (qualifier id: claude-web, chatgpt, claude-code, codex, cursor). Null = never said.';
comment on column projects.chat_last_seen_at is
  'Last MCP request carrying ?client=chat - the "chat app connected" evidence. Stamped at most every 10 minutes.';

alter table article_drafts add column if not exists pr_url text;
alter table article_drafts add column if not exists pr_number integer;
alter table article_drafts add column if not exists repo_path text;
alter table article_drafts add column if not exists pr_merged_at timestamptz;

comment on column article_drafts.repo_path is
  'Repo-relative path of the committed article file when published through a GitHub repo (e.g. content/blog/my-slug.mdx).';

-- ============ 0061_qualifier_site_kind.sql ============
-- The pre-checkout qualifier now asks "what kind of site" as a choice
-- (WordPress, or built with code on GitHub) instead of deriving it from the
-- domain probe alone, and the domain itself became optional on that screen.
-- The explicit answer is what the wizard branches on; the probe stays as the
-- safety net that refuses a Wix/Squarespace/... site behind a confident click.
alter table signup_qualifiers add column if not exists site_kind text;
alter table signup_qualifiers alter column domain drop not null;

comment on column signup_qualifiers.site_kind is
  'What the owner said the site is: wordpress | code. Null on rows from before the two-step qualifier (2026-08-20); those fall back to the detected platform.';

-- ============ 0062_setup_path.sql ============
-- The hosted setup path: one evidence-derived step at a time. Four projects
-- columns - the coding-agent "seen at the MCP door" stamp (mirror of
-- chat_last_seen_at), the agent-credential stamp, the connect-phase finish
-- stamp, and the steps the owner parked with "I'll do this later".
alter table projects
  add column if not exists agent_last_seen_at timestamptz,
  add column if not exists agent_credential_at timestamptz,
  add column if not exists setup_connected_at timestamptz,
  add column if not exists setup_deferred text[] not null default '{}';

-- Every project that already passes the cloud gate counts as connected, so none re-enters the path.
update projects
   set setup_connected_at = coalesce(pipeline_installed_at, created_at)
 where setup_connected_at is null
   and (onboarding_screen = 'c5'
        or pipeline_installed_at is not null
        or (github_repo is not null and onboarding_screen is null));

-- The two statements below touch ONLY rows the backfill above connected
-- (setup_connected_at is exactly the value it wrote), never a row the new
-- path stamped at click time: the docker stack replays this file on every
-- boot, and a replay must not rewrite a live project's state.

-- A backfilled GitHub row was installed (or set up by hand) before this path
-- existed: mark the install as fired so the path never auto-installs into a
-- legacy repo. Only when the key is absent.
update projects
   set install_progress = install_progress
         || jsonb_build_object('install_fired', coalesce(pipeline_installed_at, created_at))
 where github_repo is not null
   and setup_connected_at = coalesce(pipeline_installed_at, created_at)
   and not (install_progress ? 'install_fired');

-- Seed deferrals so Home still asks a legacy project for what it skipped
-- (WordPress, chat app, Google + its property pick) - each only when no
-- evidence already proves it (the same evidence the step engine reads), so
-- a seeded deferral can always be met. Idempotent: never over a list the
-- owner has since changed.
update projects p set setup_deferred = array_remove(array[
    case when p.publish_target = 'wordpress' and p.wp_app_password is null then 'wordpress' end,
    case when p.ai_choice in ('claude-web','chatgpt') and p.chat_last_seen_at is null
              and not exists (select 1 from article_drafts d
                              where d.project_id = p.id and d.status not in ('discarded','rejected'))
              and not exists (select 1 from site_profile sp where sp.project_id = p.id)
         then 'chat_connect' end,
    case when p.gsc_oauth_refresh_token is null
              and not exists (select 1 from gsc_stats g where g.project_id = p.id)
         then 'google_connect' end,
    case when p.gsc_oauth_refresh_token is null
              and not exists (select 1 from gsc_stats g where g.project_id = p.id)
         then 'gsc_property' end
  ]::text[], null)
 where p.setup_connected_at is not null
   and p.setup_connected_at = coalesce(p.pipeline_installed_at, p.created_at)
   and p.setup_deferred = '{}';

